<?php if (!$items): ?><p class="muted">No exchange requests yet.</p><?php endif; ?>
<?php foreach ($items as $x): ?><div class="panel"><div class="row"><strong>Order <?= e($x['order_number']) ?></strong><span class="status"><?= e($x['status']) ?></span></div>
<p><?= e($x['reason']) ?><?= $x['new_size'] ? ' &rarr; size ' . e($x['new_size']) : '' ?><?= $x['item_note'] ? ' &middot; ' . e($x['item_note']) : '' ?></p><?= $x['details'] ? '<p class="muted">' . e($x['details']) . '</p>' : '' ?><p class="muted small"><?= e($x['email']) ?> &middot; <?= e(time_ago($x['created_at'])) ?></p>
<form class="form" method="post" action="<?= e(url('admin/exchanges/' . $x['id'])) ?>"><?= csrf_field() ?><div class="form-row"><label>Status <select name="status"><?php foreach (['pending', 'approved', 'rejected', 'completed'] as $s): ?><option <?= $s === $x['status'] ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select></label><label>Note <input name="admin_note" value="<?= e($x['admin_note']) ?>"></label></div><button class="btn btn-dark btn-sm">Save</button></form></div><?php endforeach; ?>
